def populate_active_slots(apps, schema_editor):
    """Заполнить active_slot живым броням и привязать RESERVED-экземпляры к ACTIVE."""
    Reservation = apps.get_model("library", "Reservation")
    BookCopy = apps.get_model("library", "BookCopy")
    seen = set()
    for reservation in Reservation.objects.filter(status__in=["PENDING", "ACTIVE"]).order_by(
        "queue_date", "id"
    ):
        key = (reservation.reader_id, reservation.book_id)
        if key in seen:
            # Устаревшие дубликаты остаются без active_slot.
            continue
        seen.add(key)
        reservation.active_slot = 1
        if reservation.status == "ACTIVE" and reservation.copy_id is None:
            copy = (
                BookCopy.objects.filter(book_id=reservation.book_id, status="RESERVED")
                .order_by("id")
                .first()
            )
            if copy is not None:
                reservation.copy_id = copy.id
        reservation.save(update_fields=["active_slot", "copy"])


